1	import { mkdir, readdir, readFile, rmdir, stat } from "node:fs/promises";
2	import { basename, dirname, join, resolve } from "node:path";
3	import { isTagColor, TAG_COLORS, type TagColor } from "@kaipu/domain/constants";
4	import type {
5	  LocationCheck,
6	  WorkspaceCreateRefusal,
7	  WorkspaceEditRefusal,
8	  WorkspaceRelocateRefusal,
9	  WorkspaceUnavailableReason,
10	} from "@shared/types/workspaces";
11	import { newWorkspaceFolderName, validateWorkspaceName } from "@shared/workspace-name";
12	import { atomicWriteFile, withLock } from "../library/atomic-write";
13	import {
14	  DEFAULT_WORKSPACE_COLOR,
15	  DEFAULT_WORKSPACE_NAME,
16	  deriveInitials,
17	  isDirectory,
18	  isSafeWorkspaceId,
19	  isValidInitials,
20	  nextWorkspaceColor,
21	  normalizeWorkspaceName,
22	  readIdentity,
23	  removeIdentity,
24	  writeIdentity,
25	  type WorkspaceIdentity,
26	} from "./identity";
27	
28	/**
29	 * The workspace registry (ADR 0032): which folders this Mac knows and which one is active,
30	 * stored as the `workspaces` key of `userData/preferences.json`, next to the existing
31	 * `vaultDirectory`. Pure Node (no Electron), so it is tested against temp folders.
32	 *
33	 * Downgrade contract: `vaultDirectory` always mirrors the active path (absent when that is
34	 * the default folder), so an older version, which reads only that key, opens the active
35	 * workspace. An older version spreads the file it read on every write, so it keeps the
36	 * `workspaces` key; when it changed the folder, the next launch here adopts that folder.
37	 */
38	
39	/** One registered workspace. `name`, `color` and `initials` cache the folder's identity. */
40	export interface WorkspaceEntry {
41	  id: string;
42	  path: string;
43	  name: string;
44	  color: TagColor;
45	  initials?: string;
46	  addedAt: number;
47	  /** The folder was unreachable or read-only when registered: identity.json is still to write. */
48	  pendingInit?: true;
49	  /**
50	   * The name or color here is newer than the folder's `identity.json` (edited while the folder
51	   * was not connected, or upgraded then): the registry wins and is written to the folder the
52	   * next time it is reached, instead of the folder's older file overwriting it.
53	   */
54	  pendingIdentity?: true;
55	  /**
56	   * The one-time brand-color upgrade is cached here but not yet in the folder (it was not
57	   * connected). Unlike `pendingIdentity` it does not own the folder: when the folder is back
58	   * it is written only if the folder still holds the old Default and rose; a folder that
59	   * changed meanwhile (on another Mac) is adopted and the upgrade is dropped.
60	   */
61	  pendingColorUpgrade?: true;
62	}
63	
64	export interface WorkspacesKey {
65	  version: 1;
66	  activeId: string;
67	  /** Owns the cloud entries that carry no workspace id (spec decision 3). Explicit, never "the first entry". */
68	  legacyCloudOwnerId: string;
69	  /** Set once the one-time "New: workspaces" hint is dismissed. */
70	  hintDismissedAt?: number;
71	  /**
72	   * The one-time upgrade of a "Default workspace" migrated as rose to Kaipu's brand color has
73	   * run. Once set it never runs again, so a color the user picks later is never taken back.
74	   */
75	  kaipuColorApplied?: true;
76	  entries: WorkspaceEntry[];
77	}
78	
79	type StoredPreferences = Record<string, unknown> & {
80	  vaultDirectory?: string;
81	  workspaces?: unknown;
82	};
83	
84	export type PreferencesRead =
85	  | { kind: "missing" }
86	  | { kind: "ok"; preferences: StoredPreferences }
87	  | { kind: "corrupt" };
88	
89	/**
90	 * Read preferences.json strictly. Unlike the old reader, a file that does not parse is
91	 * reported, never read as `{}`: writing after that would erase a custom folder for good.
92	 */
93	export async function readPreferences(file: string): Promise<PreferencesRead> {
94	  let raw: string;
95	  try {
96	    raw = await readFile(file, "utf-8");
97	  } catch (error) {
98	    return (error as NodeJS.ErrnoException).code === "ENOENT"
99	      ? { kind: "missing" }
100	      : { kind: "corrupt" };
101	  }
102	  try {
103	    const parsed: unknown = JSON.parse(raw);
104	    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return { kind: "corrupt" };
105	    return { kind: "ok", preferences: parsed as StoredPreferences };
106	  } catch {
107	    return { kind: "corrupt" };
108	  }
109	}
110	
111	function parseEntry(value: unknown): WorkspaceEntry | null {
112	  if (!value || typeof value !== "object") return null;
113	  const record = value as Record<string, unknown>;
114	  const name = normalizeWorkspaceName(record["name"]);
115	  if (!isSafeWorkspaceId(record["id"]) || typeof record["path"] !== "string" || !name) return null;
116	  return {
117	    id: record["id"],
118	    path: record["path"],
119	    name,
120	    color: isTagColor(record["color"]) ? record["color"] : TAG_COLORS[0],
121	    ...(isValidInitials(record["initials"]) ? { initials: record["initials"] } : {}),
122	    addedAt: typeof record["addedAt"] === "number" ? record["addedAt"] : 0,
123	    ...(record["pendingInit"] === true ? { pendingInit: true as const } : {}),
124	    ...(record["pendingIdentity"] === true ? { pendingIdentity: true as const } : {}),
125	    ...(record["pendingColorUpgrade"] === true ? { pendingColorUpgrade: true as const } : {}),
126	  };
127	}
128	
129	/** The `workspaces` key, or null when it is not one this version can use. */
130	export function parseWorkspacesKey(value: unknown): WorkspacesKey | null {
131	  if (!value || typeof value !== "object") return null;
132	  const record = value as Record<string, unknown>;
133	  if (record["version"] !== 1 || !Array.isArray(record["entries"])) return null;
134	  const entries = record["entries"].map(parseEntry);
135	  if (entries.length === 0 || entries.some((e) => e === null)) return null;
136	  const valid = entries as WorkspaceEntry[];
137	  const ids = new Set(valid.map((e) => e.id));
138	  if (ids.size !== valid.length) return null;
139	  const activeId = typeof record["activeId"] === "string" ? record["activeId"] : valid[0]!.id;
140	  const owner = record["legacyCloudOwnerId"];
141	  return {
142	    version: 1,
143	    activeId,
144	    legacyCloudOwnerId: typeof owner === "string" ? owner : activeId,
145	    ...(typeof record["hintDismissedAt"] === "number"
146	      ? { hintDismissedAt: record["hintDismissedAt"] }
147	      : {}),
148	    ...(record["kaipuColorApplied"] === true ? { kaipuColorApplied: true as const } : {}),
149	    entries: valid,
150	  };
151	}
152	
153	export interface RegistryEnv {
154	  preferencesFile: string;
155	  /** The platform default library folder (Videos/Kaipu Record). */
156	  defaultDirectory: string;
157	  now?: () => number;
158	  newId: () => string;
159	  /** Called after every preferences write, so the cached `vaultDirectory()` re-reads. */
160	  onPreferencesWritten?: () => void;
161	}
162	
163	export type Availability =
164	  | { state: "available" }
165	  | { state: "unavailable"; reason: WorkspaceUnavailableReason };
166	
167	export type AddOutcome =
168	  | { ok: true; entry: WorkspaceEntry; created: boolean }
169	  | { ok: false; reason: "not-writable" | "unreadable" | "read-only" };
170	
171	export type CreateOutcome =
172	  | { ok: true; entry: WorkspaceEntry }
173	  | { ok: false; reason: WorkspaceCreateRefusal };
174	
175	export type EditOutcome =
176	  | { ok: true; entry: WorkspaceEntry; savedToFolder: boolean }
177	  | { ok: false; reason: WorkspaceEditRefusal };
178	
179	/** Whether a folder may become a workspace's new location; `workspaceName` names the other one. */
180	export type RelocateCheck =
181	  | { ok: true }
182	  | { ok: false; reason: WorkspaceRelocateRefusal; workspaceName?: string };
183	
184	export type RelocateOutcome =
185	  | { ok: true; entry: WorkspaceEntry }
186	  | { ok: false; reason: WorkspaceRelocateRefusal; workspaceName?: string };
187	
188	export type RemoveOutcome =
189	  | { ok: true }
190	  | { ok: false; reason: "active" | "last" | "unknown" | "read-only" };
191	
192	/** Dropped from the "is this folder empty?" check: Finder writes it into any folder it opens. */
193	const IGNORED_FOLDER_ENTRIES = new Set([".DS_Store"]);
194	
195	class NameTakenError extends Error {}
196	
197	const LOCK = "workspaces:registry";
198	/** Serializes `update`, so one update's rollback never discards another's change. */
199	const UPDATE_LOCK = "workspaces:registry:update";
200	
201	/** The identity the one-time brand-color upgrade starts from: the migrated Default, in rose. */
202	function isOldDefault(identity: WorkspaceIdentity): boolean {
203	  return identity.name === DEFAULT_WORKSPACE_NAME && identity.color === "rose";
204	}
205	
206	function samePath(a: string, b: string): boolean {
207	  return resolve(a) === resolve(b);
208	}
209	
210	function entryFromIdentity(
211	  identity: WorkspaceIdentity,
212	  path: string,
213	  addedAt: number,
214	): WorkspaceEntry {
215	  return {
216	    id: identity.id,
217	    path,
218	    name: identity.name,
219	    color: identity.color,
220	    ...(identity.initials ? { initials: identity.initials } : {}),
221	    addedAt,
222	  };
223	}
224	
225	export class WorkspaceRegistry {
226	  private constructor(
227	    private readonly env: RegistryEnv,
228	    private key: WorkspacesKey,
229	    /** preferences.json did not parse (or the first registration could not be written): write nothing. */
230	    readonly readOnly: boolean,
231	  ) {}
232	
233	  private static now(env: RegistryEnv): number {
234	    return env.now?.() ?? Date.now();
235	  }
236	
237	  /**
238	   * Load the registry, migrating a pre-workspaces install on its first launch and adopting a
239	   * folder an older version switched to. Additive only: it writes
240	   * `.kaipu/workspace/identity.json` and the `workspaces` key, and nothing else.
241	   */
242	  static async open(env: RegistryEnv): Promise<WorkspaceRegistry> {
243	    const read = await readPreferences(env.preferencesFile);
244	    if (read.kind === "corrupt") return WorkspaceRegistry.readOnlyFallback(env);
245	    const preferences = read.kind === "ok" ? read.preferences : {};
246	    const vaultPath =
247	      typeof preferences.vaultDirectory === "string" && preferences.vaultDirectory
248	        ? preferences.vaultDirectory
249	        : env.defaultDirectory;
250	
251	    if (preferences.workspaces === undefined) {
252	      return WorkspaceRegistry.migrate(env, vaultPath, vaultPath === env.defaultDirectory);
253	    }
254	    const key = parseWorkspacesKey(preferences.workspaces);
255	    // A key this version cannot read (hand edit, a future version): leave it alone.
256	    if (!key) return WorkspaceRegistry.readOnlyFallback(env, vaultPath);
257	    const registry = new WorkspaceRegistry(env, key, false);
258	    await registry.reconcile(vaultPath);
259	    if (!registry.key.kaipuColorApplied) await registry.upgradeDefaultColor();
260	    return registry;
261	  }
262	
263	  /** The library as today, under an in-memory id; nothing is written until the next launch. */
264	  private static async readOnlyFallback(
265	    env: RegistryEnv,
266	    path: string = env.defaultDirectory,
267	  ): Promise<WorkspaceRegistry> {
268	    const identity = await readIdentity(path);
269	    const entry: WorkspaceEntry =
270	      identity.kind === "ok"
271	        ? entryFromIdentity(identity.identity, path, 0)
272	        : {
273	            id: env.newId(),
274	            path,
275	            name: DEFAULT_WORKSPACE_NAME,
276	            color: DEFAULT_WORKSPACE_COLOR,
277	            initials: deriveInitials(DEFAULT_WORKSPACE_NAME),
278	            addedAt: 0,
279	          };
280	    return new WorkspaceRegistry(
281	      env,
282	      { version: 1, activeId: entry.id, legacyCloudOwnerId: entry.id, entries: [entry] },
283	      true,
284	    );
285	  }
