287	  /** First launch after the upgrade: the current library becomes "Default workspace". */
288	  private static async migrate(
289	    env: RegistryEnv,
290	    path: string,
291	    isDefault: boolean,
292	  ): Promise<WorkspaceRegistry> {
293	    const now = WorkspaceRegistry.now(env);
294	    // Today's behaviour: the default folder is created on first use.
295	    if (isDefault) await mkdir(path, { recursive: true }).catch(() => {});
296	    const existing = await readIdentity(path);
297	    let entry: WorkspaceEntry;
298	    if (existing.kind === "ok") {
299	      // A rerun after a crash between the two writes: reuse the id, never mint a second.
300	      entry = entryFromIdentity(existing.identity, path, now);
301	    } else {
302	      const identity: WorkspaceIdentity = {
303	        version: 1,
304	        id: env.newId(),
305	        name: DEFAULT_WORKSPACE_NAME,
306	        color: DEFAULT_WORKSPACE_COLOR,
307	        initials: deriveInitials(DEFAULT_WORKSPACE_NAME),
308	        createdAt: now,
309	      };
310	      entry = entryFromIdentity(identity, path, now);
311	      if (existing.kind === "absent") {
312	        try {
313	          await writeIdentity(path, identity);
314	        } catch {
315	          // Unplugged or read-only: registered anyway, initialized on the first reach.
316	          entry.pendingInit = true;
317	        }
318	      } else {
319	        // An identity.json we cannot read is never overwritten.
320	        entry.pendingInit = true;
321	      }
322	    }
323	    const key: WorkspacesKey = {
324	      version: 1,
325	      activeId: entry.id,
326	      legacyCloudOwnerId: entry.id,
327	      // Born with the brand color: there is nothing to upgrade, now or on a later launch.
328	      kaipuColorApplied: true,
329	      entries: [entry],
330	    };
331	    const registry = new WorkspaceRegistry(env, key, false);
332	    try {
333	      await registry.persist({ mirrorVault: false });
334	    } catch {
335	      // The registry could not be stored: run as today and retry on the next launch.
336	      return new WorkspaceRegistry(env, key, true);
337	    }
338	    return registry;
339	  }
