341	  /**
342	   * `vaultDirectory` no longer matches the active entry: an older version changed the folder
343	   * while downgraded. Adopt that folder (by its identity id, else its path, else as a new
344	   * entry) and make it active, so the change is not ignored after the re-upgrade.
345	   */
346	  private async reconcile(vaultPath: string): Promise<void> {
347	    const active = this.key.entries.find((e) => e.id === this.key.activeId);
348	    if (active && samePath(active.path, vaultPath)) return;
349	    const identity = await readIdentity(vaultPath);
350	    let target: WorkspaceEntry | undefined;
351	    if (identity.kind === "ok") {
352	      target = this.key.entries.find((e) => e.id === identity.identity.id);
353	      if (target) target.path = vaultPath;
354	    }
355	    target ??= this.key.entries.find((e) => samePath(e.path, vaultPath));
356	    if (!target) {
357	      target = await this.register(vaultPath, identity);
358	      if (!target) return; // the folder is gone too: keep the registry's own active entry
359	    }
360	    this.key.activeId = target.id;
361	    try {
362	      await this.persist({ mirrorVault: true });
363	    } catch (error) {
364	      // The app still opens that folder (vaultDirectory already names it); the registry
365	      // catches up on the next write or launch.
366	      console.error("workspaces: could not store the adopted folder", error);
367	    }
368	  }
