370	  /** Make an entry for a folder the registry does not know. Null when it cannot be reached. */
371	  private async register(
372	    path: string,
373	    identity: Awaited<ReturnType<typeof readIdentity>>,
374	  ): Promise<WorkspaceEntry | undefined> {
375	    const now = WorkspaceRegistry.now(this.env);
376	    if (identity.kind === "ok") {
377	      const entry = entryFromIdentity(identity.identity, path, now);
378	      this.key.entries.push(entry);
379	      return entry;
380	    }
381	    if (identity.kind === "unreadable" || !(await isDirectory(path))) return undefined;
382	    const name = normalizeWorkspaceName(basename(path)) ?? DEFAULT_WORKSPACE_NAME;
383	    const minted: WorkspaceIdentity = {
384	      version: 1,
385	      id: this.env.newId(),
386	      name,
387	      color: nextWorkspaceColor(this.key.entries.map((e) => e.color)),
388	      initials: deriveInitials(name),
389	      createdAt: now,
390	    };
391	    const entry = entryFromIdentity(minted, path, now);
392	    try {
393	      await writeIdentity(path, minted);
394	    } catch {
395	      entry.pendingInit = true;
396	    }
397	    this.key.entries.push(entry);
398	    return entry;
399	  }
