495	  /**
496	   * Create a workspace in a NEW folder (the owner's request, part 1b): `Kaipu Record — <name>`
497	   * next to the Default workspace's. Writes only Kaipu's own files; a folder that is there and
498	   * not empty is refused untouched. Does not switch.
499	   */
500	  async create(input: { name: string; color: string }): Promise<CreateOutcome> {
501	    if (this.readOnly) return { ok: false, reason: "read-only" };
502	    const checked = validateWorkspaceName(input.name, this.key.entries);
503	    if (!checked.ok) {
504	      return { ok: false, reason: checked.reason === "taken" ? "name-taken" : "invalid-name" };
505	    }
506	    if (!isTagColor(input.color)) return { ok: false, reason: "invalid-color" };
507	    const location = await this.checkNewLocation(checked.name);
508	    if (!location.path) return { ok: false, reason: "parent-missing" };
509	    if (location.state === "not-empty") return { ok: false, reason: "exists" };
510	
511	    const path = location.path;
512	    let madeFolder = false;
513	    if (location.state === "free") {
514	      try {
515	        // One level, never recursive: a missing parent stays missing.
516	        await mkdir(path);
517	        madeFolder = true;
518	      } catch (error) {
519	        const code = (error as NodeJS.ErrnoException).code;
520	        return { ok: false, reason: code === "EEXIST" ? "exists" : "not-writable" };
521	      }
522	    }
523	    const undo = async (): Promise<void> => {
524	      await removeIdentity(path);
525	      if (madeFolder) await rmdir(path).catch(() => {});
526	    };
527	    const identity: WorkspaceIdentity = {
528	      version: 1,
529	      id: this.env.newId(),
530	      name: checked.name,
531	      color: input.color,
532	      initials: deriveInitials(checked.name),
533	      createdAt: WorkspaceRegistry.now(this.env),
534	    };
535	    try {
536	      await writeIdentity(path, identity);
537	    } catch {
538	      await undo();
539	      return { ok: false, reason: "not-writable" };
540	    }
541	    const entry = entryFromIdentity(identity, path, identity.createdAt);
542	    try {
543	      await this.update((key) => {
544	        // Re-checked inside the write: two creates cannot both take one name.
545	        if (validateWorkspaceName(checked.name, key.entries).ok === false)
546	          throw new NameTakenError();
547	        key.entries.push(entry);
548	      });
549	    } catch (error) {
550	      await undo();
551	      return { ok: false, reason: error instanceof NameTakenError ? "name-taken" : "not-writable" };
552	    }
553	    return { ok: true, entry };
554	  }
