750	  /**
751	   * Add an existing folder. Creates only Kaipu's own files (`.kaipu/workspace/identity.json`)
752	   * and never touches the user's content. A folder with an identity is adopted: an id this
753	   * Mac knows at an unreachable path is a relocation, at a reachable one it is a copy, which
754	   * gets a new id. Does not switch.
755	   */
756	  async add(path: string): Promise<AddOutcome> {
757	    if (this.readOnly) return { ok: false, reason: "read-only" };
758	    const known = this.key.entries.find((e) => samePath(e.path, path));
759	    if (known) return { ok: true, entry: known, created: false };
760	    if (!(await isDirectory(path))) return { ok: false, reason: "not-writable" };
761	    const now = WorkspaceRegistry.now(this.env);
762	    const identity = await readIdentity(path);
763	    if (identity.kind === "unreadable") return { ok: false, reason: "unreadable" };
764	
765	    if (identity.kind === "ok") {
766	      const registered = this.get(identity.identity.id);
767	      if (registered) {
768	        const { availability } = await this.availability(registered.id);
769	        if (availability.state === "unavailable") {
770	          // The same folder at a new path (a renamed drive, a moved folder): relocate.
771	          await this.update(() => {
772	            Object.assign(
773	              registered,
774	              entryFromIdentity(identity.identity, path, registered.addedAt),
775	            );
776	            delete registered.pendingInit;
777	          });
778	          return { ok: true, entry: registered, created: false };
779	        }
780	        // A copy of a registered folder: same name, new id, so the two never share one.
781	        const copy: WorkspaceIdentity = {
782	          ...identity.identity,
783	          id: this.env.newId(),
784	          createdAt: now,
785	        };
786	        try {
787	          await writeIdentity(path, copy);
788	        } catch {
789	          return { ok: false, reason: "not-writable" };
790	        }
791	        const entry = entryFromIdentity(copy, path, now);
792	        await this.update((key) => void key.entries.push(entry));
793	        return { ok: true, entry, created: true };
794	      }
795	      const entry = entryFromIdentity(identity.identity, path, now);
796	      await this.update((key) => void key.entries.push(entry));
797	      return { ok: true, entry, created: true };
798	    }
799	
800	    const name = normalizeWorkspaceName(basename(path)) ?? DEFAULT_WORKSPACE_NAME;
801	    const minted: WorkspaceIdentity = {
802	      version: 1,
803	      id: this.env.newId(),
804	      name,
805	      color: nextWorkspaceColor(this.key.entries.map((e) => e.color)),
806	      initials: deriveInitials(name),
807	      createdAt: now,
808	    };
809	    try {
810	      await writeIdentity(path, minted);
811	    } catch {
812	      return { ok: false, reason: "not-writable" };
813	    }
814	    const entry = entryFromIdentity(minted, path, now);
815	    await this.update((key) => void key.entries.push(entry));
816	    return { ok: true, entry, created: true };
817	  }
