819	  /**
820	   * May `id` be pointed at `path`? Read-only: nothing is written, not even an identity file.
821	   * Only a folder whose `.kaipu/workspace/identity.json` carries this workspace's id qualifies.
822	   * An empty or plain folder is refused, never adopted: the workspace's items are not in it,
823	   * so every one of them would disappear from the library.
824	   */
825	  async checkRelocate(id: string, path: string): Promise<RelocateCheck> {
826	    if (this.readOnly) return { ok: false, reason: "read-only" };
827	    const entry = this.get(id);
828	    if (!entry) return { ok: false, reason: "unknown" };
829	    if (!(await isDirectory(path))) return { ok: false, reason: "not-a-folder" };
830	    const other = this.key.entries.find((e) => e.id !== id && samePath(e.path, path));
831	    if (other) return { ok: false, reason: "already-registered", workspaceName: other.name };
832	
833	    const identity = await readIdentity(path);
834	    if (identity.kind === "unreadable") return { ok: false, reason: "unreadable" };
835	    if (identity.kind === "ok") {
836	      return identity.identity.id === id
837	        ? { ok: true }
838	        : { ok: false, reason: "different", workspaceName: identity.identity.name };
839	    }
840	    // The folder it already points at, whose identity file was deleted by hand: a probe
841	    // rewrites it, so this is not a move.
842	    if (samePath(entry.path, path)) return { ok: true };
843	    if (await isDirectory(join(path, ".kaipu"))) {
844	      // A workspace registered while its folder was away never got an identity.json, so a
845	      // folder with Kaipu items and none is exactly where it can now be: the probe after the
846	      // move writes the file under the registered id. Any other workspace has an identity to
847	      // match, so a folder without one is not its own.
848	      return entry.pendingInit ? { ok: true } : { ok: false, reason: "has-items-no-identity" };
849	    }
850	    return { ok: false, reason: "not-a-workspace" };
851	  }
852	
853	  /**
854	   * "Change folder…": point `id` at the folder where it now lives (moved in Finder, put in a
855	   * Google Drive folder, a drive mounted elsewhere). Only the registry changes: no file is
856	   * moved, copied or written. Name, color and id stay. The active workspace's path is mirrored
857	   * into `vaultDirectory`; the caller runs that one inside the switch transaction.
858	   */
859	  async relocate(id: string, path: string): Promise<RelocateOutcome> {
860	    const checked = await this.checkRelocate(id, path);
861	    if (!checked.ok) return checked;
862	    try {
863	      await this.update(
864	        (key) => {
865	          const target = key.entries.find((e) => e.id === id);
866	          if (target) target.path = path;
867	        },
868	        { mirrorVault: id === this.key.activeId },
869	      );
870	    } catch {
871	      return { ok: false, reason: "not-writable" };
872	    }
873	    const entry = this.get(id);
874	    return entry ? { ok: true, entry } : { ok: false, reason: "unknown" };
875	  }
876	
877	  /** Remove from list: unregister only. Nothing on disk changes, so re-adding restores it. */
878	  async remove(id: string): Promise<RemoveOutcome> {
879	    if (this.readOnly) return { ok: false, reason: "read-only" };
880	    if (!this.get(id)) return { ok: false, reason: "unknown" };
881	    if (id === this.key.activeId) return { ok: false, reason: "active" };
882	    // Defence in depth: the active id always names an entry, so a lone entry is the active
883	    // one and was refused above. This guard only matters if that invariant ever breaks.
884	    if (this.key.entries.length <= 1) return { ok: false, reason: "last" };
885	    await this.update((key) => {
886	      key.entries = key.entries.filter((e) => e.id !== id);
887	    });
888	    return { ok: true };
889	  }
890	
891	  /** Persist the active id, and mirror its path into `vaultDirectory` for older versions. */
892	  async setActive(id: string): Promise<void> {
893	    if (this.readOnly) throw new Error("workspaces: preferences are read-only this session");
894	    if (!this.get(id)) throw new Error(`workspaces: unknown workspace ${id}`);
895	    await this.update(
896	      (key) => {
897	        key.activeId = id;
898	      },
899	      { mirrorVault: true },
900	    );
901	  }
902	
903	  async dismissHint(): Promise<void> {
904	    if (this.readOnly || this.key.hintDismissedAt !== undefined) return;
905	    await this.update((key) => {
906	      key.hintDismissedAt = WorkspaceRegistry.now(this.env);
907	    });
908	  }
909	
910	  /** An update a probe learned (a cached name, a finished init): never fails the probe. */
911	  private async refresh(mutate: (key: WorkspacesKey) => void): Promise<void> {
912	    try {
913	      // What a probe learned is true whether or not it could be written: keep it in memory.
914	      await this.update(mutate, { mirrorVault: false, rollback: false });
915	    } catch (error) {
916	      console.error("workspaces: could not store a registry update", error);
917	    }
918	  }
919	
920	  /**
921	   * Apply a change and write it. A failed write puts the registry back as it was, so a
922	   * rejected add or remove leaves nothing behind in the list.
923	   */
924	  private update(
925	    mutate: (key: WorkspacesKey) => void,
926	    options: { mirrorVault: boolean; rollback?: boolean } = { mirrorVault: false },
927	  ): Promise<void> {
928	    return withLock(UPDATE_LOCK, async () => {
929	      const before = structuredClone(this.key);
930	      mutate(this.key);
931	      if (this.readOnly) return;
932	      try {
933	        await this.persist(options);
934	      } catch (error) {
935	        if (options.rollback !== false) this.key = before;
936	        throw error;
937	      }
938	    });
939	  }
940	
941	  /**
942	   * Write the `workspaces` key (and, on a switch, the mirrored `vaultDirectory`) into the
943	   * file as it is on disk now, keeping every other key. Atomic: temp, fsync, rename.
944	   */
945	  private persist(options: { mirrorVault: boolean }): Promise<void> {
946	    return withLock(LOCK, async () => {
947	      const read = await readPreferences(this.env.preferencesFile);
948	      if (read.kind === "corrupt") throw new Error("workspaces: preferences.json does not parse");
949	      const preferences: StoredPreferences = read.kind === "ok" ? { ...read.preferences } : {};
950	      preferences.workspaces = this.key;
951	      if (options.mirrorVault) {
952	        const active = this.active();
953	        if (this.isDefaultPath(active.path)) delete preferences.vaultDirectory;
954	        else preferences.vaultDirectory = active.path;
955	      }
956	      await atomicWriteFile(this.env.preferencesFile, JSON.stringify(preferences, null, 2));
957	      this.env.onPreferencesWritten?.();
958	    });
959	  }
960	}
