4	import { TAG_COLORS, nextTagColor, type TagColor } from "@kaipu/domain/constants";
5	import { useTranslations } from "@kaipu/i18n";
6	import type {
7	  LocationCheck,
8	  WorkspaceCreateRefusal,
9	  WorkspaceCreateResult,
10	  WorkspaceEditRefusal,
11	  WorkspaceEditResult,
12	  WorkspaceRelocateResult,
13	  WorkspacesState,
14	  WorkspaceView,
15	} from "@shared/types/workspaces";
16	import { validateWorkspaceName } from "@shared/workspace-name";
17	import "@renderer/features/library/tags/tag-palette.css";
18	import { isWindowsHost } from "@renderer/features/shortcuts/host-platform";
19	import { FolderPath } from "./folder-path";
20	import { relocateRefusalMessage } from "./relocate-copy";
21	import styles from "./workspace-dialog.module.css";
