23	type Created = Extract<WorkspaceCreateResult, { ok: true }>;
24	type Saved = Extract<WorkspaceEditResult, { ok: true }>;
25	type Relocated = Extract<WorkspaceRelocateResult, { ok: true }>;
26	
27	export interface WorkspaceDialogProps {
28	  state: WorkspacesState;
29	  /** The workspace being edited, or null for "New workspace". */
30	  editing: WorkspaceView | null;
31	  onClose(): void;
32	  /** "Use an existing folder…": the folder-picker flow, for Google Drive or OneDrive folders. */
33	  onUseExisting(): void;
